//! contract: reads registry handler::host_tool_descriptors
//! PRD-mcphost-org-shared-tools-namespace-v2
//! AC2 — Given `Visibility::SHAREABLE` after `Org` is added, When the drift
//! test runs, Then the `host.tool_share` descriptor enum,
//! `contracts/host-tools.v1.json` (regenerated by `gendocs`) and
//! `parse_shareable` equal it, and `PUBLISHABLE` still excludes `org`.

use mcphost::handler::host_tool_descriptors;
use mcphost::kinds::KindRegistry;
use mcphost::sharing::Visibility;
use serde_json::Value;

fn strings(v: &Value) -> Vec<String> {
    v.as_array().unwrap_or_else(|| panic!("not an array: {v}")).iter().map(|s| s.as_str().expect("string").to_string()).collect()
}

fn names(set: &[Visibility]) -> Vec<String> {
    set.iter().map(|v| v.as_str().to_string()).collect()
}

#[test]
fn orgs_ac02() {
    let want = names(&Visibility::SHAREABLE);
    assert!(want.contains(&"org".to_string()), "SHAREABLE must hold org: {want:?}");

    // The live descriptor.
    let tools = host_tool_descriptors(&KindRegistry::with_builtin());
    let share = tools.iter().find(|t| t.name.as_ref() == "host.tool.share").expect("host.tool.share");
    assert_eq!(strings(&Value::Object((*share.input_schema).clone())["properties"]["visibility"]["enum"]), want, "descriptor enum");

    // The committed contract, the file `mcphost contract dump` writes.
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/contracts/host-tools.v1.json");
    let contract: Value = serde_json::from_str(&std::fs::read_to_string(path).expect("contract file")).expect("contract json");
    let entry = contract["tools"]
        .as_array()
        .expect("tools")
        .iter()
        .find(|t| t["name"] == "host.tool.share")
        .expect("host.tool.share in the contract");
    assert_eq!(strings(&entry["input_schema"]["properties"]["visibility"]["enum"]), want, "contract enum");

    // The validator accepts exactly the set.
    for v in Visibility::ALL {
        assert_eq!(Visibility::parse_shareable(v.as_str()).is_ok(), want.contains(&v.as_str().to_string()), "parse_shareable on '{}'", v.as_str());
    }
    assert_eq!(Visibility::parse_shareable("org").ok(), Some(Visibility::Org));

    // `org` is shareable, never publishable.
    assert!(!Visibility::PUBLISHABLE.contains(&Visibility::Org));
    assert!(Visibility::parse_publishable("org").is_err());
    let publish = tools.iter().find(|t| t.name.as_ref() == "host.tool.publish").expect("host.tool.publish");
    let publish_enum = strings(&Value::Object((*publish.input_schema).clone())["properties"]["visibility"]["enum"]);
    assert!(!publish_enum.contains(&"org".to_string()), "{publish_enum:?}");
}
